import React, { useRef } from "react";

function CounterRef() {
    const countRef = useRef(0);

    const incrementCount = () => {
        countRef.current += 1;
    }

    return (
        <button onClick={incrementCount}>Click Me (Ref)</button>
    )
}

export default CounterRef;
